<?php require __DIR__.'/config.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $email = strtolower(trim($_POST['email'])); $stmt = $db->prepare('SELECT * FROM users WHERE email=?'); $stmt->execute([$email]); $user = $stmt->fetch(PDO::FETCH_ASSOC); if (!$user || !password_verify(client_secret($_POST['password']), $user['password_hash'])) { flash('E-Mail oder Passwort ist falsch.'); header('Location: index.php'); exit; } $_SESSION['pending_user'] = $user['id']; if (AUTH_LEVEL >= 2) { $_SESSION['email_code'] = str_pad((string)random_int(0,999999), 6, '0', STR_PAD_LEFT); $_SESSION['email_code_expires'] = time()+300; error_log('[DEMO MAIL] Login-Code fuer '.$email.': '.$_SESSION['email_code']); header('Location: email-code.php'); exit; } $_SESSION['user_id'] = $user['id']; header('Location: dashboard.php'); exit; }
page('<h1>Secure Login</h1>'.show_flash().'<p>Stufe '.AUTH_LEVEL.' von 3</p><form method="post" onsubmit="return protect(this)"><input type="hidden" name="csrf" value="'.h(csrf()).'"><label>E-Mail<input type="email" name="email" required></label><label>Passwort<input type="password" name="password" required></label><button>Anmelden</button></form><p><a href="register.php">Konto anlegen</a> · <a href="reset.php">Passwort vergessen?</a></p><script>async function protect(f){let b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(f.password.value));f.password.value=Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,"0")).join("");return true}</script>');
